// Final batch: Shampooing ids 482-488 + Nail Care & Skin Care ids 489-525, closes array with ]
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/barber-questions.js')

function fmt(q, topic, topic_es) {
  return `  { id: ${q.id}, topic: ${topic}, topic_es: ${topic_es}, psi_topic: ${topic}, psi_topic_es: ${topic_es}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

// Last 7 Shampooing & Conditioning (ids 482–488)
const scT = `"Shampooing & Conditioning"`, scTes = `"Champú y Acondicionamiento"`
const scQ = [
  { id: 482, question: "A shampoo formulated for fine hair typically:", question_es: "Un champú formulado para cabello fino típicamente:", options: ["Is lightweight, free of heavy silicones or oils that would weigh fine hair down, and may contain volumizing polymers to add body", "Contains heavy conditioning agents to make fine hair feel thicker", "Uses a high pH to swell the hair shaft and create artificial volume", "Is identical to shampoos for coarse, thick hair — no differences exist"], options_es: ["Es liviano, libre de siliconas o aceites pesados que pesarían el cabello fino, y puede contener polímeros volumizadores para añadir cuerpo", "Contiene agentes acondicionadores pesados para hacer que el cabello fino se sienta más grueso", "Usa un pH alto para hinchar el eje del cabello y crear volumen artificial", "Es idéntico a los champús para cabello grueso y abundante — no existen diferencias"], correct: 0, explanation: "Fine hair is easily weighed down by heavy products. Shampoos for fine hair are formulated to cleanse effectively without leaving residue, and often include volumizing agents that add body without coating the hair shaft with heavy silicones or oils." },
  { id: 483, question: "A 'balancing shampoo' is intended for clients with:", question_es: "Un 'champú equilibrante' está destinado para clientes con:", options: ["Combination scalp conditions — oily at the roots and dry at the ends — it cleanses the oily scalp without over-drying the already dry mid-shaft and ends", "Purely oily hair requiring maximum degreasing", "Purely dry hair requiring maximum moisture infusion", "Color-treated hair that fades within two weeks of each color service"], options_es: ["Condiciones de cuero cabelludo mixtas — grasoso en las raíces y seco en las puntas — limpia el cuero cabelludo graso sin resecar demasiado el eje medio y las puntas ya secas", "Cabello puramente graso que requiere el máximo desengrasante", "Cabello puramente seco que requiere la máxima infusión de humedad", "Cabello teñido que se desvanece dentro de las dos semanas de cada servicio de color"], correct: 0, explanation: "Balancing shampoos address combination scalp/hair conditions — a common pattern where the scalp overproduces oil (oily roots) while the mid-lengths and ends are dry or damaged. Balancing formulas cleanse the scalp effectively without further dehydrating the ends." },
  { id: 484, question: "The correct order of operations for a basic shampoo and conditioning service is:", question_es: "El orden correcto de operaciones para un servicio básico de champú y acondicionamiento es:", options: ["Drape client → wet hair → apply shampoo → massage scalp → rinse → apply conditioner → process → rinse conditioner → towel blot", "Apply conditioner → wet hair → apply shampoo → drape client → rinse → towel blot", "Wet hair → drape → shampoo → condition → dry without rinsing conditioner", "Drape → dry shampoo → apply conditioner → wet → rinse all at once"], options_es: ["Cubrir al cliente con la capa → mojar el cabello → aplicar champú → masajear el cuero cabelludo → enjuagar → aplicar acondicionador → procesar → enjuagar el acondicionador → secar con toalla", "Aplicar acondicionador → mojar el cabello → aplicar champú → cubrir al cliente → enjuagar → secar con toalla", "Mojar el cabello → cubrir → champú → acondicionar → secar sin enjuagar el acondicionador", "Cubrir → champú seco → aplicar acondicionador → mojar → enjuagar todo a la vez"], correct: 0, explanation: "The correct sequence is: drape (protect client) → wet hair → apply and lather shampoo → scalp massage → rinse → apply conditioner → process (1–5 min) → rinse conditioner → towel blot. Draping first protects the client's clothing before any water is used." },
  { id: 485, question: "Applying heat (a plastic cap or warm towel) during a deep conditioning treatment helps because:", question_es: "Aplicar calor (un gorro de plástico o toalla tibia) durante un tratamiento de acondicionamiento profundo ayuda porque:", options: ["Heat opens (swells) the cuticle, allowing conditioning agents to penetrate more deeply into the cortex for better moisture and protein infusion", "Heat chemically bonds the conditioner molecules to the hair's disulfide bonds permanently", "Heat evaporates the water in the conditioner, concentrating its active ingredients at the cuticle surface", "Heat prevents the conditioner from rinsing out during the processing phase"], options_es: ["El calor abre (hincha) la cutícula, permitiendo que los agentes acondicionadores penetren más profundamente en el córtex para una mejor infusión de humedad y proteínas", "El calor une químicamente las moléculas del acondicionador a los enlaces disulfuro del cabello de forma permanente", "El calor evapora el agua en el acondicionador, concentrando sus ingredientes activos en la superficie de la cutícula", "El calor evita que el acondicionador se enjuague durante la fase de procesamiento"], correct: 0, explanation: "Heat causes the cuticle scales to swell open, creating larger pathways for conditioning molecules to penetrate from the cuticle layer into the cortex. This is why deep conditioning treatments (especially for damaged or dry hair) are often done under a hooded dryer, steam cap, or with a heated towel." },
  { id: 486, question: "Sulfate-free shampoos are recommended for color-treated hair because:", question_es: "Los champús sin sulfatos se recomiendan para el cabello con color porque:", options: ["Sulfates (like SLS) are strong cleansers that aggressively open the cuticle, allowing artificial color molecules to escape; sulfate-free formulas cleanse gently while preserving color", "Sulfate-free shampoos contain a built-in color-refreshing agent that replenishes faded tones", "Sulfates permanently bond to color molecules and make the color too dark over time", "Sulfate-free shampoos are required by TDLR for all color-treated client services"], options_es: ["Los sulfatos (como SLS) son limpiadores fuertes que abren agresivamente la cutícula, permitiendo que las moléculas de color artificial escapen; las fórmulas sin sulfatos limpian suavemente preservando el color", "Los champús sin sulfatos contienen un agente refrescante de color incorporado que repone los tonos desvanecidos", "Los sulfatos se unen permanentemente a las moléculas de color y hacen que el color se oscurezca demasiado con el tiempo", "TDLR requiere champús sin sulfatos para todos los servicios de clientes con color"], correct: 0, explanation: "Sulfate detergents (SLS, SLES) are highly effective cleansers but they also open the cuticle aggressively, allowing the artificial color molecules deposited in the cortex to wash out more quickly. Sulfate-free formulas use milder surfactants that cleanse without disrupting the cuticle as severely, extending color vibrancy." },
  { id: 487, question: "A client with dandruff should be advised to shampoo:", question_es: "Se debe aconsejar a un cliente con caspa que se lave el cabello con champú:", options: ["More frequently with a medicated anti-dandruff shampoo — regular cleansing reduces the buildup of dead skin cells and sebum that feed the Malassezia yeast", "Less frequently because shampooing worsens dandruff by removing protective oils", "Only with cold water to slow the growth of the Malassezia yeast", "With a heavy conditioning shampoo to replace the oils lost from the flaking scalp"], options_es: ["Con más frecuencia con un champú medicado anticaspa — la limpieza regular reduce la acumulación de células muertas de la piel y sebo que alimentan la levadura Malassezia", "Con menos frecuencia porque el lavado empeora la caspa al eliminar los aceites protectores", "Solo con agua fría para ralentizar el crecimiento de la levadura Malassezia", "Con un champú acondicionador pesado para reponer los aceites perdidos por la descamación del cuero cabelludo"], correct: 0, explanation: "Dandruff (seborrheic dermatitis) is exacerbated by buildup of dead skin cells and sebum. Regular shampooing with an appropriate medicated shampoo (zinc pyrithione, selenium sulfide) reduces the substrate for Malassezia yeast and mechanically removes flakes. Infrequent shampooing worsens dandruff." },
  { id: 488, question: "Conditioning treatments should NOT be applied to the scalp when:", question_es: "Los tratamientos acondicionadores NO deben aplicarse al cuero cabelludo cuando:", options: ["The client has an oily scalp or scalp conditions where heavy conditioning would worsen the condition (like seborrheic dermatitis) — conditioning agents can add to the buildup and block follicles", "The hair is longer than 6 inches", "The client's hair has been recently color-treated", "The client has fine hair — conditioner can never be used on fine hair"], options_es: ["El cliente tiene un cuero cabelludo graso o condiciones del cuero cabelludo donde el acondicionamiento pesado empeoraría la condición (como la dermatitis seborreica) — los agentes acondicionadores pueden añadirse a la acumulación y bloquear los folículos", "El cabello es más largo de 6 pulgadas", "El cabello del cliente ha sido tratado recientemente con color", "El cliente tiene cabello fino — el acondicionador nunca puede usarse en cabello fino"], correct: 0, explanation: "Heavy conditioners applied to an oily scalp or to scalps with seborrheic dermatitis can exacerbate those conditions by adding more oils/coating substances and clogging follicle openings. Conditioner should be applied only to the mid-shaft and ends for oily-scalp clients." },
]

// All 37 Nail Care & Skin Care (ids 489–525)
const ncT = `"Nail Care & Skin Care"`, ncTes = `"Cuidado de Uñas y Piel"`
const ncQ = [
  { id: 489, question: "The nail plate is composed primarily of:", question_es: "La placa ungueal está compuesta principalmente de:", options: ["Hardened, keratinized cells (keratin protein) — the same fibrous structural protein that makes up hair", "Calcified calcium deposits, like bone", "Melanin produced by nail matrix melanocytes", "Collagen fibers similar to the skin's dermis"], options_es: ["Células endurecidas y queratinizadas (proteína de queratina) — la misma proteína estructural fibrosa que compone el cabello", "Depósitos calcificados de calcio, como el hueso", "Melanina producida por los melanocitos de la matriz ungueal", "Fibras de colágeno similares a la dermis de la piel"], correct: 0, explanation: "The nail plate is made of hardened (cornified) keratin cells — the same protein found in hair. Contrary to popular belief, nails are not calcium — they are keratin. However, minerals (including calcium) in the diet do support overall nail health." },
  { id: 490, question: "The nail matrix is the part of the nail that:", question_es: "La matriz ungueal es la parte de la uña que:", options: ["Produces the nail plate — it contains actively dividing cells (onychocytes) at the nail's base that push the nail forward as they multiply and keratinize", "Anchors the nail to the fingertip bone", "Produces melanin that gives nails their natural color", "Prevents fungal organisms from entering under the nail plate"], options_es: ["Produce la placa ungueal — contiene células activamente en división (onicócitos) en la base de la uña que empujan la uña hacia adelante a medida que se multiplican y queratinizan", "Ancla la uña al hueso del dedo", "Produce melanina que da a las uñas su color natural", "Previene que los organismos fúngicos entren debajo de la placa ungueal"], correct: 0, explanation: "The nail matrix (germinal matrix) lies under the base of the nail plate, partially visible as the lunula. It contains the nail-forming cells that divide and keratinize, pushing the formed nail plate forward over the nail bed. Damage to the matrix can permanently affect nail growth." },
  { id: 491, question: "The 'lunula' is:", question_es: "La 'lúnula' es:", options: ["The half-moon shaped pale area at the base of the nail plate — it is the visible portion of the nail matrix, where new nail cells have not yet fully keratinized and thus appear lighter", "The curved edge at the tip of the nail (the free edge)", "The skin fold that overlaps the nail at its sides", "The layer of epidermis under the free edge of the nail"], options_es: ["El área pálida en forma de media luna en la base de la placa ungueal — es la porción visible de la matriz ungueal, donde las nuevas células de la uña aún no se han queratinizado completamente y por lo tanto parecen más claras", "El borde curvo en la punta de la uña (el borde libre)", "El pliegue cutáneo que superpone la uña en sus lados", "La capa de epidermis debajo del borde libre de la uña"], correct: 0, explanation: "The lunula (Latin for 'little moon') is the visible whitish, half-moon shaped area at the base of the nail. It represents the distal end of the nail matrix. It appears lighter because the cells in this zone have not yet fully keratinized and because the vascular nail bed underneath is partially covered." },
  { id: 492, question: "The 'hyponychium' is:", question_es: "El 'hiponiquio' es:", options: ["The thickened skin under the free edge of the nail — it seals the space between the nail plate and the nail bed, protecting against microbial invasion", "The skin fold at the base of the nail plate (the cuticle area)", "The skin that forms the sidewalls along the nail", "The nail's natural pigment produced by specialized matrix cells"], options_es: ["La piel engrosada debajo del borde libre de la uña — sella el espacio entre la placa ungueal y el lecho ungueal, protegiendo contra la invasión microbiana", "El pliegue cutáneo en la base de la placa ungueal (el área de la cutícula)", "La piel que forma las paredes laterales a lo largo de la uña", "El pigmento natural de la uña producido por células especializadas de la matriz"], correct: 0, explanation: "The hyponychium is the thickened epidermis under the free edge of the nail, at the junction of the nail plate and the fingertip skin. It acts as a seal to protect the nail bed from bacterial and fungal invasion. It should not be cut or aggressively cleaned, as this can create an entry point for pathogens." },
  { id: 493, question: "The eponychium (nail cuticle) is:", question_es: "El eponiquio (cutícula de la uña) es:", options: ["The dead tissue overlapping the nail plate from the nail wall — it seals the nail fold to the nail plate, protecting the matrix from bacteria", "The living skin forming the sidewalls along the nail plate", "The thickened skin under the free edge of the nail", "The half-moon visible portion of the nail matrix"], options_es: ["El tejido muerto que superpone la placa ungueal desde la pared ungueal — sella el pliegue ungueal a la placa ungueal, protegiendo la matriz de las bacterias", "La piel viva que forma las paredes laterales a lo largo de la placa ungueal", "La piel engrosada debajo del borde libre de la uña", "La porción de media luna visible de la matriz ungueal"], correct: 0, explanation: "The eponychium is the thin tissue visible at the base of the nail that adheres to the nail plate. It is dead tissue (cuticle) that seals the space between the nail plate and the nail fold (mantle), preventing bacteria from accessing the matrix. The cuticle is technically the dead tissue; the nail wall is the living tissue behind it." },
  { id: 494, question: "Nails grow at an average rate of approximately:", question_es: "Las uñas crecen a una velocidad promedio de aproximadamente:", options: ["1/8 inch (about 3 mm) per month for fingernails — toenails grow more slowly", "1 inch per month for fingernails", "1 cm per week for all nails", "Nails do not grow — they are static structures formed once"], options_es: ["1/8 de pulgada (aproximadamente 3 mm) por mes para las uñas de los dedos — las uñas de los pies crecen más lentamente", "1 pulgada por mes para las uñas de los dedos", "1 cm por semana para todas las uñas", "Las uñas no crecen — son estructuras estáticas formadas una sola vez"], correct: 0, explanation: "Fingernails grow approximately 1/8 inch (about 3 mm) per month, or about 1.5 inches per year. Toenails grow more slowly. Growth rates vary by age, hand dominance, temperature, nutrition, and overall health. It takes approximately 3–6 months to replace a complete fingernail." },
  { id: 495, question: "Onychomycosis is:", question_es: "La onicomicosis es:", options: ["A fungal infection of the nail plate — it causes the nail to become thick, brittle, discolored (yellow-brown), and may separate from the nail bed", "A bacterial infection of the skin around the nail (paronychia)", "A hereditary condition causing spoon-shaped nails (koilonychia)", "Temporary white spots on the nail plate caused by minor trauma"], options_es: ["Una infección fúngica de la placa ungueal — hace que la uña se vuelva gruesa, quebradiza, descolorada (amarillo-marrón) y puede separarse del lecho ungueal", "Una infección bacteriana de la piel alrededor de la uña (paroniquia)", "Una condición hereditaria que causa uñas en forma de cuchara (coiloniquia)", "Manchas blancas temporales en la placa ungueal causadas por traumatismo menor"], correct: 0, explanation: "Onychomycosis (tinea unguium) is a fungal infection of the nail. It is the most common nail disorder, causing thickening, discoloration (yellow, brown, white), crumbling, and potential separation (onycholysis) of the nail from the bed. A barber must refuse nail services on infected nails and refer the client to a physician." },
  { id: 496, question: "Paronychia is:", question_es: "La paroniquia es:", options: ["Bacterial (or fungal) infection of the skin surrounding the nail, causing redness, swelling, pain, and possibly pus around the nail fold", "Fungal infection inside the nail plate causing yellowing and thickening", "White spots (leukonychia) on the nail plate from minor trauma", "Abnormal separation of the nail plate from the nail bed"], options_es: ["Infección bacteriana (o fúngica) de la piel que rodea la uña, causando enrojecimiento, hinchazón, dolor y posiblemente pus alrededor del pliegue ungueal", "Infección fúngica dentro de la placa ungueal causando amarillamiento y engrosamiento", "Manchas blancas (leuconiquia) en la placa ungueal por traumatismo menor", "Separación anormal de la placa ungueal del lecho ungueal"], correct: 0, explanation: "Paronychia is an infection of the proximal and lateral nail folds. Acute paronychia is usually bacterial (Staphylococcus aureus) and presents with redness, swelling, and pain. Chronic paronychia is usually fungal or from repeated irritation. Barbers must refuse service on infected tissue and refer to a physician." },
  { id: 497, question: "Leukonychia refers to:", question_es: "La leuconiquia se refiere a:", options: ["White spots or streaks on the nail plate — usually caused by minor trauma to the nail matrix or base of the nail", "Yellow-brown discoloration from onychomycosis", "Pitting of the nail surface associated with psoriasis", "Complete shedding of the nail plate (onychoptosis)"], options_es: ["Manchas o rayas blancas en la placa ungueal — generalmente causadas por traumatismo menor en la matriz ungueal o base de la uña", "Decoloración amarillo-marrón por onicomicosis", "Picado de la superficie ungueal asociado con psoriasis", "Desprendimiento completo de la placa ungueal (onicoptosis)"], correct: 0, explanation: "Leukonychia (white nails) refers to the appearance of white spots, streaks, or patches on the nail plate. The most common form (leukonychia punctata) consists of small white spots caused by minor trauma to the nail matrix. It is generally harmless and grows out with the nail." },
  { id: 498, question: "A nail file should be moved:", question_es: "Una lima de uñas debe moverse:", options: ["In one direction only (from the side to the center of the free edge) — back-and-forth sawing motions cause the nail layers to split and peel", "Back and forth in a rapid sawing motion for fastest results", "Only across the top of the nail plate to buff", "Only in a circular motion around the perimeter of the free edge"], options_es: ["En una sola dirección (del lado al centro del borde libre) — los movimientos de aserrado de ida y vuelta hacen que las capas de la uña se partan y se despellejen", "De ida y vuelta en un rápido movimiento de aserrado para los resultados más rápidos", "Solo a través de la parte superior de la placa ungueal para pulir", "Solo en movimiento circular alrededor del perímetro del borde libre"], correct: 0, explanation: "Filing in one direction (from side to center, then from the other side to center) prevents the nail layers from separating (delaminating). Back-and-forth sawing creates heat and friction that causes the nail layers to split and peel — especially problematic for thin or brittle nails." },
  { id: 499, question: "The correct implement to use for pushing back the cuticle during a nail care service is:", question_es: "El implemento correcto para empujar la cutícula hacia atrás durante un servicio de cuidado de uñas es:", options: ["A wooden or rubber-tipped cuticle pusher — gently pushes the softened cuticle back without cutting the living nail wall", "A cuticle nipper to cut away all cuticle tissue", "A metal nail file to scrape back the cuticle", "A stiff-bristle nail brush to brush the cuticle backward"], options_es: ["Un empujador de cutícula de madera o con punta de goma — empuja suavemente la cutícula ablandada hacia atrás sin cortar la pared viva de la uña", "Un cortacutículas para cortar todo el tejido de la cutícula", "Una lima de uñas de metal para raspar la cutícula hacia atrás", "Un cepillo de uñas de cerdas rígidas para cepillar la cutícula hacia atrás"], correct: 0, explanation: "The cuticle pusher (wood or rubber-tip) is the correct tool for gently pushing back softened cuticle tissue after a cuticle softener has been applied. Cutting the living nail wall (perionychium) with nippers can cause bleeding, pain, and infection. Only dead cuticle tissue (epithelial tissue adhering to the nail plate) may be removed." },
  { id: 500, question: "Before performing any nail care service, the barber must examine the client's nails to:", question_es: "Antes de realizar cualquier servicio de cuidado de uñas, el barbero debe examinar las uñas del cliente para:", options: ["Identify any nail disorders, fungal infections, injuries, or contraindications that would prevent safe nail service", "Estimate how long the service will take", "Determine the client's preferred nail shape", "Assess the client's overall health by reading the nail plate color"], options_es: ["Identificar cualquier trastorno de las uñas, infecciones fúngicas, lesiones o contraindicaciones que impedirían un servicio de uñas seguro", "Estimar cuánto tiempo tomará el servicio", "Determinar la forma de uña preferida del cliente", "Evaluar la salud general del cliente leyendo el color de la placa ungueal"], correct: 0, explanation: "A pre-service nail examination is essential to identify conditions (fungal infection, paronychia, open wounds, or nail disorders) that contraindicate service. Performing nail services over infected or diseased tissue risks spreading the condition to other clients via implements, and can worsen the client's condition." },
  { id: 501, question: "The three primary layers of the skin are:", question_es: "Las tres capas primarias de la piel son:", options: ["Epidermis (outermost), dermis (middle), and subcutaneous tissue/hypodermis (deepest — fatty layer)", "Cuticle (outer), cortex (middle), and medulla (core)", "Stratum corneum, stratum spinosum, and stratum basale only", "Mucosa, submucosa, and muscularis"], options_es: ["Epidermis (más externa), dermis (media) e hipodermis/tejido subcutáneo (más profundo — capa grasa)", "Cutícula (externa), córtex (media) y médula (núcleo)", "Solo estrato córneo, estrato espinoso y estrato basal", "Mucosa, submucosa y muscular"], correct: 0, explanation: "The skin has three layers: the epidermis (outermost, avascular protective layer), the dermis (middle layer containing blood vessels, nerves, hair follicles, and glands), and the subcutaneous layer/hypodermis (deepest, adipose/fatty layer that insulates and cushions). Hair anatomy terms (cuticle/cortex/medulla) apply to the hair shaft, not the skin." },
  { id: 502, question: "The layer of the epidermis where new skin cells are produced through cell division (mitosis) is:", question_es: "La capa de la epidermis donde se producen nuevas células de piel a través de la división celular (mitosis) es:", options: ["Stratum germinativum (stratum basale) — the deepest epidermal layer, containing actively dividing basal cells and melanocytes", "Stratum corneum — the outermost layer of dead, flattened cells", "Stratum granulosum — the granular layer where cells begin to die", "Stratum lucidum — the clear layer found only on the palms and soles"], options_es: ["Estrato germinativo (estrato basal) — la capa epidérmica más profunda, que contiene células basales activamente en división y melanocitos", "Estrato córneo — la capa más externa de células muertas y aplanadas", "Estrato granuloso — la capa granular donde las células comienzan a morir", "Estrato lúcido — la capa clara encontrada solo en las palmas y las plantas"], correct: 0, explanation: "The stratum germinativum (basale) is the deepest layer of the epidermis where cell division (mitosis) continuously produces new keratinocytes. These new cells push older cells upward through successive layers until they reach the surface as dead, flat corneocytes (stratum corneum) and shed off." },
  { id: 503, question: "Melanocytes are cells found in the skin that:", question_es: "Los melanocitos son células encontradas en la piel que:", options: ["Produce melanin, the pigment that gives skin and hair their color and provides protection against UV radiation", "Form the structural scaffold (collagen/elastin) of the dermis", "Fight bacterial infections as part of the skin's immune response", "Produce sebum (oil) to lubricate the skin surface"], options_es: ["Producen melanina, el pigmento que da color a la piel y el cabello y proporciona protección contra la radiación UV", "Forman el andamio estructural (colágeno/elastina) de la dermis", "Combaten las infecciones bacterianas como parte de la respuesta inmune de la piel", "Producen sebo (aceite) para lubricar la superficie de la piel"], correct: 0, explanation: "Melanocytes are specialized cells located primarily in the stratum basale. They produce melanin through a process called melanogenesis and distribute it to surrounding keratinocytes. Melanin absorbs UV radiation, protecting the DNA of skin cells. Variations in melanocyte activity produce different skin tones." },
  { id: 504, question: "Sebaceous glands in the skin produce:", question_es: "Las glándulas sebáceas en la piel producen:", options: ["Sebum — an oily secretion that lubricates and waterproofs the skin and hair shaft, and has mild antibacterial properties", "Sweat (eccrine secretion) for temperature regulation", "Melanin for UV protection", "Collagen to maintain skin elasticity and firmness"], options_es: ["Sebo — una secreción aceitosa que lubrica e impermeabiliza la piel y el eje del cabello, y tiene leves propiedades antibacterianas", "Sudor (secreción ecrina) para la regulación de la temperatura", "Melanina para la protección UV", "Colágeno para mantener la elasticidad y firmeza de la piel"], correct: 0, explanation: "Sebaceous glands are attached to hair follicles throughout most of the body. They secrete sebum into the follicle, which travels up to the skin surface. Sebum lubricates and moisturizes the hair and skin, forms part of the acid mantle, and has mild antimicrobial activity." },
  { id: 505, question: "Pseudofolliculitis barbae (razor bumps) is a condition that:", question_es: "La pseudofoliculitis barbae (pelos encarnados) es una condición que:", options: ["Occurs when shaved hairs curl back and re-enter the skin, causing a foreign-body inflammatory reaction — most common in clients with tightly coiled, curly hair", "Is caused by a bacterial infection of the hair follicle", "Is an allergic reaction to shaving cream or aftershave products", "Only occurs in clients who do not properly cleanse the face before shaving"], options_es: ["Ocurre cuando los pelos afeitados se curvan de regreso y vuelven a entrar en la piel, causando una reacción inflamatoria de cuerpo extraño — más común en clientes con cabello muy rizado y apretado", "Es causada por una infección bacteriana del folículo piloso", "Es una reacción alérgica a la crema de afeitar o productos para después del afeitado", "Solo ocurre en clientes que no limpian adecuadamente el rostro antes del afeitado"], correct: 0, explanation: "Pseudofolliculitis barbae (PFB) is caused by the sharp cut end of a curly hair that curves back into the skin as it grows, creating a foreign-body inflammatory reaction. It is most prevalent in clients with tightly coiled hair types. Management includes single-blade razors, proper shaving direction, and exfoliation." },
  { id: 506, question: "Keloids differ from normal scars in that:", question_es: "Los queloides difieren de las cicatrices normales en que:", options: ["Keloids are raised, overgrown scar tissue that extends beyond the boundary of the original wound — caused by excessive collagen production during healing; they may itch or be painful", "Keloids heal completely within 6 months, unlike permanent scars", "Normal scars are raised and keloids are flat", "Keloids only form on the scalp and beard area"], options_es: ["Los queloides son tejido cicatricial elevado y sobredimensionado que se extiende más allá del límite de la herida original — causados por la producción excesiva de colágeno durante la curación; pueden picar o ser dolorosos", "Los queloides se curan completamente dentro de los 6 meses, a diferencia de las cicatrices permanentes", "Las cicatrices normales están elevadas y los queloides son planos", "Los queloides solo se forman en el cuero cabelludo y el área de la barba"], correct: 0, explanation: "Keloids result from excessive collagen production during wound healing. The scar tissue overgrows the original wound boundaries. Keloids are more common in individuals with darker skin tones. They do not resolve on their own and may require medical treatment. Barbers must be gentle around keloidal skin to prevent further trauma." },
  { id: 507, question: "Acne vulgaris is characterized by:", question_es: "El acné vulgar se caracteriza por:", options: ["Clogged follicles producing comedones (blackheads/whiteheads), papules, pustules, and in severe cases, nodules or cysts — caused by excess sebum, dead skin cells, and Cutibacterium acnes bacteria", "Flat, pigmented spots from UV overexposure (solar lentigines)", "A contagious bacterial infection of the hair follicle (folliculitis)", "Red, flushed areas across the cheeks and nose from dilated capillaries (rosacea)"], options_es: ["Folículos obstruidos que producen comedones (puntos negros/blancos), pápulas, pústulas y en casos severos, nódulos o quistes — causados por exceso de sebo, células muertas de la piel y bacterias Cutibacterium acnes", "Manchas pigmentadas planas por sobreexposición UV (léntigos solares)", "Una infección bacteriana contagiosa del folículo piloso (foliculitis)", "Áreas rojas y sonrojadas en las mejillas y la nariz por capilares dilatados (rosácea)"], correct: 0, explanation: "Acne vulgaris involves follicular plugging (comedones), inflammation from C. acnes bacteria, and excess sebum production. Comedones (open = blackhead, closed = whitehead), papules (small red bumps), and pustules (pus-filled) are the primary lesions. Nodules and cysts indicate severe acne requiring medical care." },
  { id: 508, question: "Rosacea is a chronic skin condition that:", question_es: "La rosácea es una condición cutánea crónica que:", options: ["Causes persistent facial redness, visible blood vessels (telangiectasia), and sometimes papules/pustules — primarily affects the central face; triggers include heat, spicy food, and alcohol", "Is caused by a fungal infection of the facial skin", "Presents as flat, dark spots from post-inflammatory hyperpigmentation", "Is the same condition as acne vulgaris — differentiated only by severity"], options_es: ["Causa enrojecimiento facial persistente, vasos sanguíneos visibles (telangiectasia) y a veces pápulas/pústulas — afecta principalmente el rostro central; los desencadenantes incluyen el calor, la comida picante y el alcohol", "Es causada por una infección fúngica de la piel facial", "Se presenta como manchas oscuras planas por hiperpigmentación post-inflamatoria", "Es la misma condición que el acné vulgar — diferenciada solo por la gravedad"], correct: 0, explanation: "Rosacea is a chronic inflammatory skin condition causing flushing, persistent redness, visible blood vessels, and sometimes papules/pustules on the central face (cheeks, nose, chin, forehead). Unlike acne, rosacea is not caused by bacteria and is not related to sebum plugging. It has no cure but is manageable." },
  { id: 509, question: "When a barber applies a hot towel (steamed towel) to a client's face before a shave, the purpose is to:", question_es: "Cuando un barbero aplica una toalla caliente (toalla al vapor) en el rostro de un cliente antes de afeitarse, el propósito es:", options: ["Soften the beard hair and open the hair follicle, making the hair easier to cut and reducing the risk of razor drag and irritation", "Chemically soften the protein bonds of the beard hair to cause permanent thinning", "Disinfect the face before shaving by killing bacteria on the skin surface with heat", "Temporarily remove excess sebum to improve razor blade adhesion"], options_es: ["Suavizar el vello de la barba y abrir el folículo piloso, facilitando el corte del cabello y reduciendo el riesgo de arrastre de la navaja e irritación", "Ablandar químicamente los enlaces de proteínas del vello de la barba para causar adelgazamiento permanente", "Desinfectar el rostro antes del afeitado matando bacterias en la superficie de la piel con calor", "Eliminar temporalmente el exceso de sebo para mejorar la adhesión de la cuchilla de afeitar"], correct: 0, explanation: "A hot towel applied before shaving hydrates and softens the coarse beard hair (beard hair is much thicker than scalp hair), swells the hair shaft with moisture, and relaxes the follicle. This reduces razor drag, allows for a closer, more comfortable shave, and minimizes skin irritation." },
  { id: 510, question: "The five basic skin types recognized in professional practice are:", question_es: "Los cinco tipos básicos de piel reconocidos en la práctica profesional son:", options: ["Normal, oily, dry, combination, and sensitive", "Fair, medium, olive, tan, and dark (Fitzpatrick scale)", "Wet, semi-wet, balanced, semi-dry, and dry", "Type I, II, III, IV, and V (UV sensitivity scale only)"], options_es: ["Normal, grasa, seca, mixta y sensible", "Clara, media, oliva, bronceada y oscura (escala de Fitzpatrick)", "Húmeda, semi-húmeda, equilibrada, semi-seca y seca", "Tipo I, II, III, IV y V (solo escala de sensibilidad UV)"], correct: 0, explanation: "The five professional skin types are: normal (balanced), oily (excess sebum, enlarged pores), dry (insufficient sebum or moisture), combination (typically oily T-zone, dry cheeks), and sensitive (reactive, prone to irritation). Each type requires different product choices and service considerations." },
  { id: 511, question: "A facial cleanser used before a barbering facial service should be selected based on:", question_es: "Un limpiador facial utilizado antes de un servicio facial de barbería debe seleccionarse en base a:", options: ["The client's skin type — oily skin needs a gel or foaming cleanser, dry skin needs a cream or lotion cleanser, sensitive skin needs a gentle, fragrance-free formula", "The barber's preference for scent and texture", "Whichever cleanser is nearest the service station", "The client's hair type, since scalp and facial skin share the same characteristics"], options_es: ["El tipo de piel del cliente — la piel grasa necesita un limpiador en gel o espuma, la piel seca necesita un limpiador en crema o loción, la piel sensible necesita una fórmula suave y sin fragancia", "La preferencia del barbero por el aroma y la textura", "El limpiador que esté más cerca de la estación de servicio", "El tipo de cabello del cliente, ya que el cuero cabelludo y la piel facial comparten las mismas características"], correct: 0, explanation: "Cleanser selection is determined by skin type. Gel/foaming cleansers are effective for oily skin. Cream/lotion cleansers provide moisture for dry skin. Micellar or gentle cleansers minimize irritation for sensitive skin. Matching the product to the client's skin type ensures effective cleansing without worsening the condition." },
  { id: 512, question: "After a close facial shave service, the barber should apply an aftershave or post-shave product to:", question_es: "Después de un servicio de afeitado facial cercano, el barbero debe aplicar un aftershave o producto post-afeitado para:", options: ["Soothe and calm the skin, close the pores, reduce inflammation from razor contact, and provide mild antiseptic action on any micro-nicks", "Re-open the pores for deep cleansing after shaving", "Apply color to even out the skin tone after the service", "Remove all remaining shaving lather from the face"], options_es: ["Calmar y tranquilizar la piel, cerrar los poros, reducir la inflamación por el contacto de la navaja y proporcionar acción antiséptica leve en cualquier micro-corte", "Reabrir los poros para una limpieza profunda después del afeitado", "Aplicar color para igualar el tono de la piel después del servicio", "Eliminar toda la espuma de afeitar restante del rostro"], correct: 0, explanation: "Post-shave products (aftershave balm, toner, astringent) soothe irritated skin, reduce redness, close pores that opened during the warm shaving process, and provide antiseptic protection for micro-nicks. They complete the shave service and improve client comfort." },
  { id: 513, question: "The barber's scope of practice for skin care services in Texas is limited to:", question_es: "El alcance de práctica del barbero para los servicios de cuidado de la piel en Texas se limita a:", options: ["Superficial skin care of the face, neck, and scalp related to barbering services — such as cleansing, moisturizing, hot/cold towel applications, and facial massage — not deep chemical treatments", "Full esthetic services equivalent to a licensed esthetician", "Any skin care service the client requests without limitation", "Only the application of aftershave products — no other skin care"], options_es: ["Cuidado superficial de la piel del rostro, cuello y cuero cabelludo relacionado con los servicios de barbería — como limpieza, hidratación, aplicaciones de toallas calientes/frías y masaje facial — no tratamientos químicos profundos", "Servicios estéticos completos equivalentes a los de un esteticista con licencia", "Cualquier servicio de cuidado de la piel que el cliente solicite sin limitación", "Solo la aplicación de productos para después del afeitado — sin otro cuidado de la piel"], correct: 0, explanation: "A Texas Class A Barber may perform superficial skin care services (cleansing, moisturizing, steaming, towel applications, and massage) of the face, scalp, and neck as part of barbering services. Advanced esthetic procedures (chemical peels, microdermabrasion, etc.) are outside the barber's scope and require an esthetician license." },
  { id: 514, question: "A cold towel applied to the face after a shave service serves to:", question_es: "Una toalla fría aplicada al rostro después de un servicio de afeitado sirve para:", options: ["Constrict blood vessels and close pores, reducing post-shave redness and soothing skin that may have been slightly irritated by the razor", "Further soften the beard hair for a second-pass shave", "Stimulate circulation and warm the skin before product application", "Disinfect the skin by cooling it below the temperature bacteria can survive"], options_es: ["Constreñir los vasos sanguíneos y cerrar los poros, reduciendo el enrojecimiento post-afeitado y calmando la piel que puede haber sido ligeramente irritada por la navaja", "Ablandar aún más el vello de la barba para un segundo pase de afeitado", "Estimular la circulación y calentar la piel antes de la aplicación de productos", "Desinfectar la piel enfriándola por debajo de la temperatura a la que las bacterias pueden sobrevivir"], correct: 0, explanation: "Cold towels cause vasoconstriction — narrowing of blood vessels — which closes pores, reduces redness and puffiness, and soothes skin that was warmed and opened during the hot-towel-and-shave process. Cold therapy is a standard step in the barber's complete shave service protocol." },
  { id: 515, question: "Facial massage in a barbering context improves the client's skin by:", question_es: "El masaje facial en el contexto de la barbería mejora la piel del cliente mediante:", options: ["Increasing blood circulation to the face (bringing oxygen and nutrients to the skin), relaxing facial muscles, and potentially stimulating lymph drainage", "Permanently tightening loose skin through mechanical stretching", "Exfoliating dead skin cells from the stratum corneum through friction", "Depositing nutrients from massage cream into the dermis through osmosis"], options_es: ["Aumentando la circulación sanguínea en el rostro (llevando oxígeno y nutrientes a la piel), relajando los músculos faciales y potencialmente estimulando el drenaje linfático", "Tensando permanentemente la piel floja mediante estiramiento mecánico", "Exfoliando células muertas de la piel del estrato córneo a través de la fricción", "Depositando nutrientes de la crema de masaje en la dermis a través de la ósmosis"], correct: 0, explanation: "Facial massage increases local blood flow, bringing more oxygen and nutrients to the skin. It relaxes the muscles of the face and neck, reduces tension, and can stimulate lymphatic drainage. The results are temporary but contribute to the overall quality of the barber's service and client experience." },
  { id: 516, question: "Hyperpigmentation of the skin refers to:", question_es: "La hiperpigmentación de la piel se refiere a:", options: ["Darkened areas of skin caused by overproduction of melanin — can result from sun exposure, post-inflammatory hyperpigmentation (PIH) from acne or shaving irritation, or hormonal factors", "Lightened patches of skin where melanocytes have been destroyed (vitiligo)", "Redness from dilated capillaries on the cheeks and nose (rosacea)", "Temporary flushing from emotional or temperature-related vasodilation"], options_es: ["Áreas oscurecidas de piel causadas por la sobreproducción de melanina — pueden resultar de la exposición solar, hiperpigmentación post-inflamatoria (HPI) por acné o irritación del afeitado, o factores hormonales", "Parches aclarados de piel donde los melanocitos han sido destruidos (vitiligo)", "Enrojecimiento por capilares dilatados en las mejillas y la nariz (rosácea)", "Rubor temporal por vasodilatación emocional o relacionada con la temperatura"], correct: 0, explanation: "Hyperpigmentation occurs when melanocytes overproduce melanin in localized areas. Common causes include UV exposure (solar lentigines/age spots), post-inflammatory hyperpigmentation (PIH) from acne lesions or shaving irritation, and hormonal changes (melasma). It is especially relevant for barbers serving clients with PFB who may develop PIH." },
  { id: 517, question: "The barber must refer a client to a dermatologist or physician when:", question_es: "El barbero debe referir a un cliente a un dermatólogo o médico cuando:", options: ["The client presents with skin or nail conditions that appear to require medical diagnosis or treatment — such as suspicious lesions, undiagnosed rashes, or signs of infection beyond the barber's scope to treat", "The client's hair is too thick to cut without a medical consultation", "The client has not had a physical examination in the past year", "The client wants a service the barber does not typically offer"], options_es: ["El cliente presenta condiciones de piel o uñas que parecen requerir diagnóstico o tratamiento médico — como lesiones sospechosas, erupciones sin diagnóstico o signos de infección más allá del alcance del barbero para tratar", "El cabello del cliente es demasiado grueso para cortarlo sin consulta médica", "El cliente no ha tenido un examen físico en el último año", "El cliente quiere un servicio que el barbero normalmente no ofrece"], correct: 0, explanation: "Barbers are not licensed to diagnose or treat medical conditions. When a client presents with suspicious skin lesions (possible skin cancer), undiagnosed conditions, or signs of infection, the barber must decline service in the affected area and refer the client to a physician or dermatologist for evaluation." },
  { id: 518, question: "The nail's 'free edge' is:", question_es: "El 'borde libre' de la uña es:", options: ["The portion of the nail plate that extends beyond the fingertip — it is the part that is filed and shaped during nail care services", "The base of the nail plate where it contacts the lunula", "The skin fold that covers the base of the nail plate", "The hyponychium that seals the nail bed from below"], options_es: ["La porción de la placa ungueal que se extiende más allá de la yema del dedo — es la parte que se lima y da forma durante los servicios de cuidado de uñas", "La base de la placa ungueal donde contacta con la lúnula", "El pliegue cutáneo que cubre la base de la placa ungueal", "El hiponiquio que sella el lecho ungueal desde abajo"], correct: 0, explanation: "The free edge is the distal, unsupported portion of the nail plate that extends past the end of the fingertip. It is the part that is trimmed, filed, and shaped during nail care. The free edge varies in length based on the client's preference and the desired nail shape." },
  { id: 519, question: "Onychauxis refers to:", question_es: "La onicauxis se refiere a:", options: ["Abnormal thickening of the nail plate — caused by systemic disease, trauma, fungal infection, or age; the nail becomes thick and may be difficult to cut normally", "Brittleness and splitting of the nail plate", "Loss of the nail plate entirely", "White, opaque discoloration of the nail plate"], options_es: ["Engrosamiento anormal de la placa ungueal — causado por enfermedad sistémica, traumatismo, infección fúngica o edad; la uña se vuelve gruesa y puede ser difícil de cortar normalmente", "Fragilidad y división de la placa ungueal", "Pérdida total de la placa ungueal", "Decoloración blanca y opaca de la placa ungueal"], correct: 0, explanation: "Onychauxis is an abnormal thickening and hardening of the nail plate. Causes include systemic conditions (psoriasis, thyroid disorders), poor circulation, chronic trauma, or fungal infection. Affected nails may be discolored and require medical care. Service on significantly thickened nails with unknown etiology warrants physician referral." },
  { id: 520, question: "Beau's lines are:", question_es: "Las líneas de Beau son:", options: ["Horizontal depressions (grooves) running across the nail plate caused by temporary disruption of nail matrix activity — from severe illness, high fever, surgery, or trauma", "Vertical ridges on the nail plate that are a normal part of aging", "Yellow staining from the prolonged use of nail polish without a base coat", "Dark longitudinal streaks in the nail plate from a pigmented lesion (melanonychia)"], options_es: ["Depresiones horizontales (surcos) que corren a través de la placa ungueal causadas por interrupción temporal de la actividad de la matriz ungueal — por enfermedad grave, fiebre alta, cirugía o trauma", "Crestas verticales en la placa ungueal que son una parte normal del envejecimiento", "Manchas amarillas por el uso prolongado de esmalte de uñas sin una base", "Rayas longitudinales oscuras en la placa ungueal de una lesión pigmentada (melanoniquia)"], correct: 0, explanation: "Beau's lines are horizontal furrows or indentations across the nail plate that reflect a past period of severely disrupted nail growth. They are caused by temporary cessation of nail matrix activity from a significant physical insult (illness, trauma, malnutrition). They grow out with the nail over months." },
  { id: 521, question: "A nail buffer is used to:", question_es: "Un pulidor de uñas se usa para:", options: ["Smooth ridges on the nail plate surface and create a natural shine — buffing in one direction across the nail plate removes minor surface irregularities", "Remove the cuticle from around the nail perimeter", "Apply nail hardener evenly across the nail surface", "Clean under the free edge of the nail"], options_es: ["Suavizar las crestas en la superficie de la placa ungueal y crear un brillo natural — pulir en una dirección a través de la placa ungueal elimina pequeñas irregularidades superficiales", "Eliminar la cutícula alrededor del perímetro de la uña", "Aplicar endurecedor de uñas uniformemente en la superficie de la uña", "Limpiar debajo del borde libre de la uña"], correct: 0, explanation: "A nail buffer is a multi-sided implement that smooths the nail plate surface. Progressive sides (coarse to fine to polish) reduce ridges and surface roughness, then create a natural shine through friction. Buffing one direction prevents heat buildup from excessive friction. Over-buffing thins the nail plate." },
  { id: 522, question: "Contraindications for a barber's facial skin care service include:", question_es: "Las contraindicaciones para el servicio de cuidado de la piel facial del barbero incluyen:", options: ["Open wounds or abrasions, contagious skin conditions (impetigo, ringworm), severe cystic acne, undiagnosed rashes, or any condition the barber suspects requires medical attention", "Dry skin — dry skin clients should not receive any facial services", "The presence of any facial hair — only clean-shaven clients may receive facial services", "Clients over 60 — aging skin is too fragile for facial services"], options_es: ["Heridas abiertas o abrasiones, condiciones cutáneas contagiosas (impétigo, tiña), acné quístico severo, erupciones sin diagnóstico o cualquier condición que el barbero sospeche requiere atención médica", "Piel seca — los clientes con piel seca no deben recibir ningún servicio facial", "La presencia de cualquier vello facial — solo los clientes afeitados pueden recibir servicios faciales", "Clientes mayores de 60 años — la piel envejecida es demasiado frágil para los servicios faciales"], correct: 0, explanation: "Contraindications for facial services include: open wounds, abrasions (risk of infection), contagious conditions (impetigo, herpes simplex, ringworm — can spread through tools/hands), severe cystic acne (manipulation can worsen), and undiagnosed lesions (may require medical diagnosis). Dry skin and age alone are not contraindications." },
  { id: 523, question: "The function of the skin as the body's first line of defense means:", question_es: "La función de la piel como la primera línea de defensa del cuerpo significa:", options: ["Intact skin acts as a physical barrier preventing bacteria, viruses, fungi, and parasites from entering the body — this is why maintaining skin integrity during barbering is critical", "The skin produces antibodies against all known pathogens", "The skin generates UV radiation to kill surface microorganisms", "The epidermis contains specialized white blood cells that neutralize all incoming pathogens"], options_es: ["La piel intacta actúa como una barrera física que evita que bacterias, virus, hongos y parásitos entren al cuerpo — esta es la razón por la que mantener la integridad de la piel durante la barbería es crítico", "La piel produce anticuerpos contra todos los patógenos conocidos", "La piel genera radiación UV para matar microorganismos en la superficie", "La epidermis contiene glóbulos blancos especializados que neutralizan todos los patógenos entrantes"], correct: 0, explanation: "The skin's primary defense function is as a physical barrier. Intact skin prevents pathogens from entering the body. Any break in skin integrity (nick, abrasion, cut) creates an entry point for infection. This is why barbers must disinfect tools, apply styptic carefully, and recognize when not to service compromised skin." },
  { id: 524, question: "Sudoriferous (sweat) glands in the skin serve which primary function?", question_es: "Las glándulas sudoríparas (de sudor) en la piel sirven principalmente para qué función?", options: ["Thermoregulation — they produce and secrete sweat which, as it evaporates from the skin surface, cools the body and helps maintain core temperature", "Lubrication of the skin and hair shaft", "Producing melanin to protect against UV radiation", "Secreting oil (sebum) into the hair follicle"], options_es: ["Termorregulación — producen y secretan sudor que, al evaporarse de la superficie de la piel, enfría el cuerpo y ayuda a mantener la temperatura central", "Lubricación de la piel y el eje del cabello", "Producir melanina para proteger contra la radiación UV", "Secretar aceite (sebo) en el folículo piloso"], correct: 0, explanation: "Eccrine sweat glands (the primary type) are found throughout the body and regulate body temperature through evaporative cooling. When body temperature rises, sweat is secreted onto the skin surface and cools the body as it evaporates. Apocrine glands (in armpits/groin) are associated with body odor." },
  { id: 525, question: "The most important safety precaution when performing nail care services in a barbershop is:", question_es: "La precaución de seguridad más importante al realizar servicios de cuidado de uñas en una barbería es:", options: ["Proper disinfection of all nail implements between clients — nail files, buffers, pushers, and nippers can transfer fungal spores, bacteria, and viruses if not properly cleaned and disinfected after each use", "Wearing safety goggles to protect from nail dust", "Using only waterless hand sanitizer rather than soap and water before nail services", "Removing all nail polish from the client's nails before performing any service"], options_es: ["Desinfección adecuada de todos los implementos de uñas entre clientes — las limas, pulidores, empujadores y cortacutículas pueden transferir esporas de hongos, bacterias y virus si no se limpian y desinfectan adecuadamente después de cada uso", "Usar gafas de seguridad para protegerse del polvo de uñas", "Usar solo desinfectante de manos sin agua en lugar de jabón y agua antes de los servicios de uñas", "Eliminar todo el esmalte de uñas del cliente antes de realizar cualquier servicio"], correct: 0, explanation: "Nail implements are a primary vector for transmitting nail fungus (onychomycosis), bacteria (paronychia), and other pathogens between clients. All nail tools must be properly cleaned, disinfected, and stored after each client. Non-porous implements (metal) can be disinfected; porous items (nail files/buffers) should be single-use or client-dedicated." },
]

let out = readFileSync(FILE, 'utf8')
out += scQ.map(q => fmt(q, scT, scTes)).join('\n') + '\n'
out += '\n// ─── NAIL CARE & SKIN CARE (ids 489–525) ────────────────────────────────────\n'
out += ncQ.map(q => fmt(q, ncT, ncTes)).join('\n') + '\n'
out += ']\n'
writeFileSync(FILE, out, 'utf8')
